  function renderProducts() {
    const grid = document.getElementById("productGrid");
    if (!grid) return;
    grid.innerHTML = products.map(p => {
      const priceHTML = p.was
        ? `<span class="was">${fmt(p.was)}</span><span class="sale-price">${fmt(p.price)}</span>`
        : fmt(p.price);
      const badge = p.badge === "sale"
        ? `<span class="product-badge sale">Sale</span>`
        : p.badge === "new" ? `<span class="product-badge new">New</span>` : "";
      return `
        <li class="product">
          <div class="product-media">
            <div class="swatch" style="background:${p.swatch}">${shapeSVG(p.shape)}</div>
            ${badge}
