:root {
  --bg: #fbfaf7;
  --surface: #ffffff;
  --ink: #14140f;
  --ink-2: #4a4a44;
  --ink-3: #6f6f68;
  --line: #e7e3da;
  --line-2: #d4cfc2;
  --accent: #1f3b2d;
  --accent-ink: #ffffff;
  --accent-soft: #eef2ec;
  --sale: #b1432b;
  --warm-1: #efe7d8;
  --warm-2: #e3d6bd;
  --warm-3: #d8c8a8;
  --shadow: 0 1px 2px rgba(20,20,15,.04), 0 8px 24px rgba(20,20,15,.06);
  --radius: 14px;
  --radius-sm: 8px;
  --maxw: 1240px;
  --step: clamp(1rem, 2.5vw, 1.75rem);
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: "Inter", "Helvetica Neue", system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  color: var(--ink);
  background: var(--bg);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

img, svg { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
a:hover { text-decoration: underline; text-underline-offset: 3px; }

h1, h2, h3 {
  font-family: "Fraunces", "Times New Roman", Georgia, serif;
  font-weight: 500;
  letter-spacing: -.01em;
  line-height: 1.15;
  margin: 0;
}
h1 { font-size: clamp(2rem, 5vw, 3.6rem); letter-spacing: -.02em; }
h2 { font-size: clamp(1.5rem, 3vw, 2.25rem); }
h3 { font-size: 1.125rem; font-weight: 600; font-family: inherit; letter-spacing: -.005em; }

.eyebrow {
  font-size: .75rem;
  text-transform: uppercase;
  letter-spacing: .14em;
  color: var(--ink-3);
  margin: 0 0 .5rem;
  font-weight: 600;
}

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

/* Focus */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

.skip-link {
  position: absolute;
  left: 1rem; top: -40px;
  background: var(--ink);
  color: #fff;
  padding: .6rem .9rem;
  border-radius: 6px;
  z-index: 100;
  transition: top .15s ease;
}
.skip-link:focus { top: 1rem; }

/* HEADER */
.site-header {
  position: sticky; top: 0; z-index: 50;
  background: rgba(251,250,247,.85);
  backdrop-filter: saturate(140%) blur(10px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: .9rem 1.25rem;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 1.5rem;
}
.brand {
  display: inline-flex; align-items: center; gap: .55rem;
  font-family: "Fraunces", Georgia, serif;
  font-size: 1.15rem;
  font-weight: 600;
  letter-spacing: -.01em;
}
.brand-mark { font-size: 1.4rem; color: var(--accent); }
.brand:hover { text-decoration: none; }

.primary-nav ul {
  list-style: none; padding: 0; margin: 0;
  display: flex; gap: 1.75rem; justify-content: center;
}
.primary-nav a {
  font-size: .95rem;
  color: var(--ink-2);
  padding: .25rem 0;
}
.primary-nav a:hover { color: var(--ink); }

.header-actions {
  display: inline-flex; gap: .25rem; align-items: center;
}
.icon-btn {
  position: relative;
  background: transparent;
  border: 1px solid transparent;
  color: var(--ink);
  width: 40px; height: 40px;
  border-radius: 999px;
  display: inline-grid; place-items: center;
  cursor: pointer;
}
.icon-btn:hover { background: var(--accent-soft); }
.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  min-width: 18px; height: 18px;
  padding: 0 4px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: .7rem;
  font-weight: 700;
  border-radius: 999px;
  display: inline-grid; place-items: center;
  line-height: 1;
}

/* BUTTONS */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  gap: .5rem;
  padding: .85rem 1.4rem;
  border-radius: 999px;
  border: 1px solid transparent;
  font-weight: 600;
  font-size: .95rem;
  cursor: pointer;
  transition: transform .08s ease, background .15s ease, color .15s ease;
  font-family: inherit;
  min-height: 44px;
}
.btn:active { transform: translateY(1px); }
.btn-primary { background: var(--accent); color: var(--accent-ink); }
.btn-primary:hover { background: #142a1f; text-decoration: none; }
.btn-ghost { background: transparent; color: var(--ink); border-color: var(--line-2); }
.btn-ghost:hover { background: var(--surface); text-decoration: none; }
.btn-light { background: var(--surface); color: var(--ink); border-color: var(--line); }
.btn-light:hover { background: var(--bg); text-decoration: none; }

.link-arrow {
  font-weight: 600;
  color: var(--ink);
  border-bottom: 1px solid var(--line-2);
  padding-bottom: 2px;
}
.link-arrow:hover { border-color: var(--ink); text-decoration: none; }

/* HERO */
.hero {
  position: relative;
  max-width: var(--maxw);
  margin: 0 auto;
  padding: clamp(2.5rem, 6vw, 5rem) 1.25rem clamp(2.5rem, 5vw, 4.5rem);
  display: grid;
  grid-template-columns: 1.1fr .9fr;
  gap: clamp(1.5rem, 4vw, 3.5rem);
  align-items: center;
}
.hero-content { max-width: 36rem; }
.hero-sub {
  font-size: 1.125rem; color: var(--ink-2);
  margin: 1.25rem 0 2rem;
