}
.hero-actions { display: flex; flex-wrap: wrap; gap: .75rem; }

.hero-art {
  position: relative;
  aspect-ratio: 5 / 4;
  border-radius: 24px;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 70% 30%, #f4ead4 0%, #e6d4ad 55%, #c8a973 100%);
}
