}
.shape-3 {
  width: 18%; height: 18%; bottom: 18%; right: 22%;
  background: radial-gradient(circle at 40% 40%, #f6e9c8, #8a6224);
  box-shadow: 0 14px 30px rgba(70,55,20,.22);
}

/* VALUE STRIP */
.value-strip {
  border-block: 1px solid var(--line);
  background: var(--surface);
}
.value-strip ul {
  max-width: var(--maxw); margin: 0 auto;
  padding: 1rem 1.25rem;
  list-style: none;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
  font-size: .95rem;
  color: var(--ink-2);
}
.value-strip li { text-align: center; }
.value-strip strong { color: var(--ink); }

/* SECTIONS */
.section {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: clamp(3rem, 6vw, 5rem) 1.25rem;
}
.section-head {
  display: flex;
