  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: .55rem .9rem;
  font-size: .85rem;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  min-height: 36px;
