  transition: opacity .18s ease, transform .18s ease;
}
.product:hover .add-btn,
.product:focus-within .add-btn { opacity: 1; transform: none; }
.add-btn:hover { background: var(--ink); color: #fff; }

.product-meta {
  display: flex; justify-content: space-between; gap: 1rem;
  align-items: baseline;
}
.product-name {
  font-size: 1rem; font-weight: 600; margin: 0;
}
.product-name a { color: inherit; }
.product-cat { font-size: .85rem; color: var(--ink-3); margin: .15rem 0 0; }
.product-price { white-space: nowrap; font-weight: 600; }
.product-price .was {
  color: var(--ink-3); text-decoration: line-through;
  font-weight: 400; margin-right: .4rem; font-size: .9em;
}
.product-price .sale-price { color: var(--sale); }

/* DEALS */
.deals-section {
  background: var(--accent);
  color: #f3efe6;
  max-width: none;
  padding: clamp(3rem, 6vw, 5rem) 1.25rem;
}
.deals-section .section-head {
  max-width: var(--maxw);
  margin-inline: auto;
}
.deals-section .eyebrow,
.deals-section .countdown { color: #c5cdc1; }
.deals-section h2 { color: #fff; }
.countdown {
  font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: .95rem;
  background: rgba(255,255,255,.08);
  padding: .5rem .85rem;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,.12);
}
.countdown #countdown { color: #fff; font-weight: 600; }

.deals-grid {
  max-width: var(--maxw); margin: 0 auto;
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 1.25rem;
}
.deal {
  background: var(--surface);
  color: var(--ink);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
  box-shadow: var(--shadow);
}
.deal-large { grid-row: span 1; }
.deal-art {
  aspect-ratio: 5/3;
  background: var(--warm-2);
  position: relative;
}
.deal-large .deal-art { aspect-ratio: 5/3.4; }
.art-a { background: linear-gradient(135deg, #d8c8a8 0%, #b08e5b 100%); }
.art-a::before {
  content:""; position:absolute; inset: 22% 18% 18% 22%;
