  box-shadow: 0 30px 60px rgba(60,40,15,.25);
}
.art-b { background: linear-gradient(160deg, #efe7d8, #c8a973); }
.art-b::before {
  content:""; position:absolute; inset: 30% 30%;
  background: radial-gradient(circle, #fff, #a07a3c);
  border-radius: 50%;
  box-shadow: 0 18px 40px rgba(60,40,15,.25);
}
.art-c { background: linear-gradient(160deg, #e9e2d2, #b9a784); }
.art-c::before {
  content:""; position:absolute; inset: 20% 15% 15% 20%;
