  border-radius: 6px;
}
.badge-sale { background: #fce8e2; color: var(--sale); }
.deal-body p { margin: 0; color: var(--ink-2); font-size: .95rem; }
.deal-body .btn { margin-top: .6rem; }

/* EDITORIAL */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
