.art-f::before {
  content:""; position:absolute; inset: 15% 20%;
  background: repeating-linear-gradient(0deg, rgba(255,255,255,.4) 0 6px, transparent 6px 14px),
              linear-gradient(180deg, #f8f4e9, #6f6a58);
