.story-body h3 { margin: .3rem 0 .4rem; font-size: 1.15rem; }
.story-feature .story-body h3 { font-size: 1.5rem; font-family: "Fraunces", Georgia, serif; font-weight: 500; }
.story-body p { color: var(--ink-2); margin: 0; }
.story-body a { color: inherit; }

/* NEWSLETTER */
.newsletter {
  background: var(--accent-soft);
  border-block: 1px solid var(--line);
}
.newsletter-inner {
  max-width: var(--maxw); margin: 0 auto;
  padding: clamp(2.5rem, 5vw, 4rem) 1.25rem;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  align-items: center;
}
.newsletter h2 { font-size: clamp(1.5rem, 3vw, 2.25rem); }
.newsletter p { color: var(--ink-2); margin: .75rem 0 0; max-width: 32rem; }
.newsletter-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: .5rem;
  align-items: stretch;
}
.newsletter-form input {
  font: inherit;
  padding: .85rem 1rem;
  border-radius: 999px;
  border: 1px solid var(--line-2);
  background: #fff;
  color: var(--ink);
  min-height: 44px;
}
.newsletter-form input:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-color: var(--accent);
}
.newsletter-status {
  grid-column: 1 / -1;
  margin: .25rem 0 0;
  font-size: .9rem;
  color: var(--ink-2);
  min-height: 1.2em;
}
.newsletter-status.error { color: var(--sale); }
.newsletter-status.success { color: var(--accent); }

/* FOOTER */
.site-footer {
  background: var(--surface);
  border-top: 1px solid var(--line);
  margin-top: 0;
}
.footer-inner {
  max-width: var(--maxw); margin: 0 auto;
  padding: clamp(2.5rem, 5vw, 4rem) 1.25rem 1.5rem;
  display: grid;
  grid-template-columns: 1.2fr 2fr;
  gap: 2.5rem;
}
.footer-brand p { color: var(--ink-3); max-width: 22rem; margin-top: .75rem; }
.site-footer nav { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; }
.footer-col h2 {
  font-family: inherit;
  font-size: .8rem;
  text-transform: uppercase;
  letter-spacing: .12em;
  color: var(--ink-3);
  margin: 0 0 .9rem;
  font-weight: 700;
}
.footer-col ul { list-style: none; padding: 0; margin: 0; display: grid; gap: .55rem; }
.footer-col a { color: var(--ink-2); font-size: .95rem; }
.footer-col a:hover { color: var(--ink); }
.copyright {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 1rem 1.25rem 2rem;
  color: var(--ink-3);
  font-size: .85rem;
}

/* TOAST */
.toast {
  position: fixed; left: 50%; bottom: 1.5rem;
  transform: translate(-50%, 200%);
  background: var(--ink);
  color: #fff;
  padding: .75rem 1.1rem;
  border-radius: 999px;
  font-size: .9rem;
  box-shadow: var(--shadow);
  transition: transform .25s ease;
  z-index: 100;
  pointer-events: none;
}
.toast.show { transform: translate(-50%, 0); }

/* RESPONSIVE */
@media (max-width: 920px) {
  .hero { grid-template-columns: 1fr; }
  .hero-art { order: -1; }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-large { grid-column: span 2; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .story-feature { grid-column: span 2; }
  .newsletter-inner { grid-template-columns: 1fr; }
  .footer-inner { grid-template-columns: 1fr; }
}
@media (max-width: 680px) {
  .primary-nav { display: none; }
  .header-inner { grid-template-columns: auto 1fr auto; }
  .value-strip ul { grid-template-columns: 1fr 1fr; text-align: left; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-large { grid-column: span 1; }
  .editorial-grid { grid-template-columns: 1fr; }
  .story-feature { grid-column: span 1; }
  .site-footer nav { grid-template-columns: 1fr 1fr; }
  .add-btn { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  * { animation-duration: 0ms !important; transition-duration: 0ms !important; }
  html { scroll-behavior: auto; }
}

@media (forced-colors: active) {
  .btn, .icon-btn, .deal, .product-media, .story-art, .hero-art {
    border: 1px solid CanvasText;
  }
  .btn-primary { background: ButtonText; color: ButtonFace; }
}

(() => {
  "use strict";

  const products = [
    { id: "p1", name: "Halden Lounge Chair",  cat: "Furniture",  price: 1290, was: null, badge: "new",
      swatch: "linear-gradient(160deg,#d8c8a8,#8a6224)", shape: "chair" },
    { id: "p2", name: "Aino Stoneware Set",   cat: "Tableware",  price: 148,  was: 198,  badge: "sale",
      swatch: "linear-gradient(160deg,#efe7d8,#b9925c)", shape: "bowl" },
    { id: "p3", name: "Linen Throw — Oat",     cat: "Textiles",   price: 96,   was: null, badge: null,
      swatch: "linear-gradient(160deg,#f1e8d2,#b8a37a)", shape: "throw" },
    { id: "p4", name: "Norré Floor Lamp",      cat: "Lighting",   price: 380,  was: null, badge: "new",
      swatch: "linear-gradient(160deg,#e9e2d2,#5b4a2c)", shape: "lamp" },
    { id: "p5", name: "Kallio Vase, Tall",     cat: "Ceramics",   price: 84,   was: 110,  badge: "sale",
      swatch: "linear-gradient(160deg,#e3d6bd,#7a5a2a)", shape: "vase" },
    { id: "p6", name: "Heath Wool Cushion",    cat: "Textiles",   price: 72,   was: null, badge: null,
      swatch: "linear-gradient(160deg,#e7e3da,#7a8472)", shape: "cushion" },
    { id: "p7", name: "Oslo Coffee Table",     cat: "Furniture",  price: 720,  was: null, badge: null,
      swatch: "linear-gradient(160deg,#d8c8a8,#6f5630)", shape: "table" },
    { id: "p8", name: "Brass Candle Holder",   cat: "Objects",    price: 58,   was: 78,   badge: "sale",
      swatch: "linear-gradient(160deg,#f4ead4,#a07a2c)", shape: "candle" },
  ];

  const fmt = (n) => "$" + n.toFixed(0);

  function shapeSVG(kind) {
    const s = {
      chair:  '<rect x="60" y="120" width="180" height="80" rx="12" fill="rgba(255,255,255,.35)"/><rect x="80" y="60" width="140" height="90" rx="14" fill="rgba(255,255,255,.5)"/>',
      bowl:   '<ellipse cx="150" cy="180" rx="100" ry="22" fill="rgba(0,0,0,.15)"/><path d="M60 140 Q150 230 240 140 Z" fill="rgba(255,255,255,.6)"/>',
      throw:  '<rect x="40" y="80" width="220" height="160" rx="10" fill="rgba(255,255,255,.5)"/><path d="M40 140 H260 M40 180 H260" stroke="rgba(0,0,0,.12)" stroke-width="2"/>',
      lamp:   '<rect x="140" y="60" width="20" height="180" fill="rgba(255,255,255,.55)"/><path d="M100 60 L200 60 L180 110 L120 110 Z" fill="rgba(255,255,255,.7)"/><ellipse cx="150" cy="246" rx="50" ry="8" fill="rgba(0,0,0,.18)"/>',
      vase:   '<path d="M120 70 H180 L170 110 Q200 150 200 200 Q200 240 150 240 Q100 240 100 200 Q100 150 130 110 Z" fill="rgba(255,255,255,.6)"/>',
      cushion:'<rect x="60" y="80" width="180" height="140" rx="22" fill="rgba(255,255,255,.55)"/>',
      table:  '<ellipse cx="150" cy="120" rx="110" ry="22" fill="rgba(255,255,255,.55)"/><rect x="60" y="120" width="180" height="14" fill="rgba(255,255,255,.7)"/><rect x="80" y="134" width="8" height="90" fill="rgba(0,0,0,.25)"/><rect x="212" y="134" width="8" height="90" fill="rgba(0,0,0,.25)"/>',
      candle: '<rect x="120" y="80" width="60" height="100" rx="6" fill="rgba(255,255,255,.55)"/><rect x="100" y="180" width="100" height="12" rx="3" fill="rgba(255,255,255,.7)"/><path d="M150 60 q6 10 0 20 q-6 -10 0 -20" fill="#ffe28a"/>',
    };
    return `<svg viewBox="0 0 300 300" width="100%" height="100%" preserveAspectRatio="xMidYMid slice" aria-hidden="true">${s[kind] || ""}</svg>`;
  }

  function renderProducts() {
    const grid = document.getElementById("productGrid");
    if (!grid) return;
    grid.innerHTML = products.map(p => {
      const priceHTML = p.was
        ? `<span class="was">${fmt(p.was)}</span><span class="sale-price">${fmt(p.price)}</span>`
        : fmt(p.price);
      const badge = p.badge === "sale"
        ? `<span class="product-badge sale">Sale</span>`
        : p.badge === "new" ? `<span class="product-badge new">New</span>` : "";
      return `
        <li class="product">
          <div class="product-media">
            <div class="swatch" style="background:${p.swatch}">${shapeSVG(p.shape)}</div>
            ${badge}
            <button class="add-btn" type="button" data-id="${p.id}" aria-label="Add ${p.name} to cart">Add to cart</button>
          </div>
          <div class="product-meta">
            <div>
              <h3 class="product-name"><a href="#">${p.name}</a></h3>
              <p class="product-cat">${p.cat}</p>
            </div>
            <p class="product-price">${priceHTML}</p>
          </div>
        </li>`;
    }).join("");
  }

  // Cart
  let cartItems = 0;
  const cartCount = document.getElementById("cartCount");
  const cartBtn = document.getElementById("cartBtn");
  const toast = document.getElementById("toast");
  let toastTimer;

  function showToast(msg) {
    if (!toast) return;
    toast.textContent = msg;
    toast.classList.add("show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => toast.classList.remove("show"), 2200);
  }

  document.addEventListener("click", (e) => {
    const btn = e.target.closest(".add-btn");
    if (!btn) return;
    cartItems++;
    cartCount.textContent = String(cartItems);
    cartBtn.setAttribute("aria-label", `Cart, ${cartItems} item${cartItems === 1 ? "" : "s"}`);
    const product = products.find(p => p.id === btn.dataset.id);
    showToast(`Added ${product ? product.name : "item"} to cart`);
  });

  // Countdown — ends at next midnight UTC of today
  const cdEl = document.getElementById("countdown");
  if (cdEl) {
    const end = new Date();
    end.setHours(23, 59, 59, 0);
    function tick() {
      const now = new Date();
      let diff = Math.max(0, Math.floor((end - now) / 1000));
      if (diff === 0) {
        end.setDate(end.getDate() + 1);
        diff = Math.max(0, Math.floor((end - now) / 1000));
      }
      const h = String(Math.floor(diff / 3600)).padStart(2, "0");
      const m = String(Math.floor((diff % 3600) / 60)).padStart(2, "0");
      const s = String(diff % 60).padStart(2, "0");
      cdEl.textContent = `${h}:${m}:${s}`;
    }
    tick();
    setInterval(tick, 1000);
  }

  // Newsletter
  const form = document.getElementById("newsletterForm");
  const status = document.getElementById("newsletter-status");
  if (form) {
    form.addEventListener("submit", (e) => {
      e.preventDefault();
      const input = form.querySelector("#email");
      const value = input.value.trim();
      const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
      status.classList.remove("error", "success");
      if (!valid) {
        status.textContent = "Please enter a valid email address.";
        status.classList.add("error");
        input.focus();
        return;
      }
      status.textContent = `Thanks — we'll send the next letter to ${value}.`;
      status.classList.add("success");
      form.reset();
    });
  }

  renderProducts();
})();

