+  display: grid;
+  grid-template-columns: 1.4fr 1fr 1fr;
+  gap: 1.25rem;
+}
+.deal {
+  background: var(--surface);
+  color: var(--ink);
+  border-radius: var(--radius);
+  overflow: hidden;
+  display: flex; flex-direction: column;
+  box-shadow: var(--shadow);
+}
+.deal-large { grid-row: span 1; }
+.deal-art {
+  aspect-ratio: 5/3;
+  background: var(--warm-2);
+  position: relative;
+}
+.deal-large .deal-art { aspect-ratio: 5/3.4; }
+.art-a { background: linear-gradient(135deg, #d8c8a8 0%, #b08e5b 100%); }
+.art-a::before {
+  content:""; position:absolute; inset: 22% 18% 18% 22%;
+  background: radial-gradient(circle at 30% 30%, #fff8e7, #8a6224);
+  border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;
+  box-shadow: 0 30px 60px rgba(60,40,15,.25);
+}
+.art-b { background: linear-gradient(160deg, #efe7d8, #c8a973); }
+.art-b::before {
+  content:""; position:absolute; inset: 30% 30%;
+  background: radial-gradient(circle, #fff, #a07a3c);
+  border-radius: 50%;
+  box-shadow: 0 18px 40px rgba(60,40,15,.25);
+}
+.art-c { background: linear-gradient(160deg, #e9e2d2, #b9a784); }
+.art-c::before {
+  content:""; position:absolute; inset: 20% 15% 15% 20%;
+  background: repeating-linear-gradient(45deg, #fff8e7 0 12px, #d8c8a8 12px 24px);
+  border-radius: 8px;
+  transform: rotate(-3deg);
+}
+.deal-body {
+  padding: 1.4rem 1.4rem 1.6rem;
+  display: flex; flex-direction: column; gap: .5rem;
+  align-items: flex-start;
+}
+.badge {
+  display: inline-block;
+  font-size: .75rem;
+  font-weight: 700;
+  letter-spacing: .08em;
+  text-transform: uppercase;
+  padding: .3rem .55rem;
+  border-radius: 6px;
+}
+.badge-sale { background: #fce8e2; color: var(--sale); }
+.deal-body p { margin: 0; color: var(--ink-2); font-size: .95rem; }
+.deal-body .btn { margin-top: .6rem; }
+
+/* EDITORIAL */
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 1.4fr 1fr 1fr;
+  gap: 1.5rem;
+}
+.story { display: flex; flex-direction: column; }
+.story-art {
+  aspect-ratio: 4/3;
+  border-radius: var(--radius);
+  margin-bottom: 1rem;
+}
+.story-feature .story-art { aspect-ratio: 4/3.2; }
+.art-d { background: linear-gradient(135deg, #c8d4c4, #5b6e58); position: relative; }
+.art-d::before {
+  content:""; position:absolute; inset: 25%;
+  background: radial-gradient(circle at 35% 35%, #f3efe6, #2c3a29);
+  border-radius: 50%;
+}
+.art-e { background: linear-gradient(160deg, #f0e3d0, #b58866); position: relative; }
+.art-e::before {
+  content:""; position:absolute; left: 20%; right: 20%; bottom: 0; top: 30%;
+  background: linear-gradient(180deg, #fff8e7, #5a3a1c);
+  border-radius: 12px 12px 0 0;
+}
+.art-f { background: linear-gradient(160deg, #e7e3da, #8a8676); position: relative; }
+.art-f::before {
+  content:""; position:absolute; inset: 15% 20%;
+  background: repeating-linear-gradient(0deg, rgba(255,255,255,.4) 0 6px, transparent 6px 14px),
+              linear-gradient(180deg, #f8f4e9, #6f6a58);
+  border-radius: 6px;
+}
+.story-body h3 { margin: .3rem 0 .4rem; font-size: 1.15rem; }
+.story-feature .story-body h3 { font-size: 1.5rem; font-family: "Fraunces", Georgia, serif; font-weight: 500; }
+.story-body p { color: var(--ink-2); margin: 0; }
+.story-body a { color: inherit; }
+
+/* NEWSLETTER */
+.newsletter {
+  background: var(--accent-soft);
+  border-block: 1px solid var(--line);
+}
+.newsletter-inner {
+  max-width: var(--maxw); margin: 0 auto;
+  padding: clamp(2.5rem, 5vw, 4rem) 1.25rem;
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 2rem;
+  align-items: center;
+}
+.newsletter h2 { font-size: clamp(1.5rem, 3vw, 2.25rem); }
+.newsletter p { color: var(--ink-2); margin: .75rem 0 0; max-width: 32rem; }
+.newsletter-form {
+  display: grid;
+  grid-template-columns: 1fr auto;
+  gap: .5rem;
+  align-items: stretch;
+}
+.newsletter-form input {
+  font: inherit;
+  padding: .85rem 1rem;
+  border-radius: 999px;
+  border: 1px solid var(--line-2);
+  background: #fff;
+  color: var(--ink);
+  min-height: 44px;
+}
+.newsletter-form input:focus-visible {
+  outline: 2px solid var(--accent);
+  outline-offset: 2px;
+  border-color: var(--accent);
+}
+.newsletter-status {
+  grid-column: 1 / -1;
+  margin: .25rem 0 0;
+  font-size: .9rem;
+  color: var(--ink-2);
+  min-height: 1.2em;
+}
+.newsletter-status.error { color: var(--sale); }
+.newsletter-status.success { color: var(--accent); }
+
+/* FOOTER */
+.site-footer {
+  background: var(--surface);
+  border-top: 1px solid var(--line);
+  margin-top: 0;
+}
+.footer-inner {
+  max-width: var(--maxw); margin: 0 auto;
+  padding: clamp(2.5rem, 5vw, 4rem) 1.25rem 1.5rem;
+  display: grid;
+  grid-template-columns: 1.2fr 2fr;
+  gap: 2.5rem;
+}
+.footer-brand p { color: var(--ink-3); max-width: 22rem; margin-top: .75rem; }
+.site-footer nav { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; }
+.footer-col h2 {
+  font-family: inherit;
+  font-size: .8rem;
+  text-transform: uppercase;
+  letter-spacing: .12em;
+  color: var(--ink-3);
+  margin: 0 0 .9rem;
+  font-weight: 700;
+}
+.footer-col ul { list-style: none; padding: 0; margin: 0; display: grid; gap: .55rem; }
+.footer-col a { color: var(--ink-2); font-size: .95rem; }
+.footer-col a:hover { color: var(--ink); }
+.copyright {
+  max-width: var(--maxw);
+  margin: 0 auto;
+  padding: 1rem 1.25rem 2rem;
+  color: var(--ink-3);
+  font-size: .85rem;
+}
+
+/* TOAST */
+.toast {
+  position: fixed; left: 50%; bottom: 1.5rem;
+  transform: translate(-50%, 200%);
+  background: var(--ink);
+  color: #fff;
+  padding: .75rem 1.1rem;
+  border-radius: 999px;
+  font-size: .9rem;
+  box-shadow: var(--shadow);
+  transition: transform .25s ease;
+  z-index: 100;
+  pointer-events: none;
+}
+.toast.show { transform: translate(-50%, 0); }
+
+/* RESPONSIVE */
+@media (max-width: 920px) {
+  .hero { grid-template-columns: 1fr; }
+  .hero-art { order: -1; }
+  .deals-grid { grid-template-columns: 1fr 1fr; }
+  .deal-large { grid-column: span 2; }
+  .editorial-grid { grid-template-columns: 1fr 1fr; }
+  .story-feature { grid-column: span 2; }
+  .newsletter-inner { grid-template-columns: 1fr; }
+  .footer-inner { grid-template-columns: 1fr; }
+}
+@media (max-width: 680px) {
+  .primary-nav { display: none; }
+  .header-inner { grid-template-columns: auto 1fr auto; }
+  .value-strip ul { grid-template-columns: 1fr 1fr; text-align: left; }
+  .deals-grid { grid-template-columns: 1fr; }
