+      vase:   '<path d="M120 70 H180 L170 110 Q200 150 200 200 Q200 240 150 240 Q100 240 100 200 Q100 150 130 110 Z" fill="rgba(255,255,255,.6)"/>',
+      cushion:'<rect x="60" y="80" width="180" height="140" rx="22" fill="rgba(255,255,255,.55)"/>',
